/**
 * The EV Charging Station Franchise and Operation Agreement's fixed legal
 * text — preamble, recitals, the 27 numbered clauses, and the static
 * boilerplate of Schedules III and IV and the Annexure. Unlike the Letter of
 * Intent, this is never edited per lead (it's the same legal language for
 * every deal); only Schedule I (see AGREEMENT_SCHEDULE_FIELDS in
 * constants.ts, plus the Site Holder and Payment Model selections on
 * AgreementDoc), and Schedule II (chargingStationItems / infrastructureItems
 * on AgreementDoc) vary deal to deal. Sourced from the Livanto Standard
 * Franchise and Operation Agreement MASTER.
 *
 * Unlike the earlier Scenario A/B version of this template, the clause text
 * itself no longer forks per Site Holder — each affected clause is drafted
 * to read correctly on its own, qualified in-line ("where Livanto is the
 * Site Holder" / "where the Franchisee is the Site Holder") rather than
 * being duplicated as parallel Scenario-A and Scenario-B paragraphs.
 */

export interface AgreementClause {
  number: string;
  heading: string;
  paragraphs: string[];
}

